import sys

def max_happiness(n, m, a, subarrays):
    # Initialize the dp table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp table
    for j in range(1, m + 1):
        l, r = subarrays[j - 1]
        for i in range(1, n + 1):
            if l <= i <= r:
                dp[j][i] = max(dp[j - 1][i], dp[j - 1][i - 1] + a[i - 1])
            else:
                dp[j][i] = dp[j - 1][i]

    # The result is the maximum value in the last row of the dp table
    return max(dp[m])

